let context,master;export const sound={enabled:true,volume:.45,async unlock(){if(!this.enabled)return;try{context||=new(window.AudioContext||window.webkitAudioContext)();if(!master){master=context.createGain();master.connect(context.destination);}master.gain.value=this.volume;if(context.state==='suspended')await context.resume();}catch{}},play(name){if(!this.enabled||!context||context.state!=='running')return;const t=context.currentTime,o=context.createOscillator(),g=context.createGain();o.connect(g);g.connect(master);const pair={select:[460,620],collect:[660,1100],build:[280,440],complete:[520,900],error:[150,100],order:[300,380],attack:[90,40],win:[440,880],alert:[700,350]}[name]||[400,550];o.type=name==='attack'?'sawtooth':'sine';o.frequency.setValueAtTime(pair[0],t);o.frequency.exponentialRampToValueAtTime(pair[1],t+.12);g.gain.setValueAtTime(name==='attack'?.03:.07,t);g.gain.exponentialRampToValueAtTime(.001,t+.16);o.start(t);o.stop(t+.18);},get state(){return context?.state||'inactive';}};
